/* ---- server ---------------------------------------------------------- */

/* Handlers: return OK and fill the results, or an ERR_* for the client.
 * A NULL handler answers ERR_NOT_SUPPORTED. A `later` method's handler
 * also gets the request's txn, and may return IDL_LATER and answer it
 * with crasher_reply_<method> (now, or later from anywhere). An event's
 * handler returns nothing (nothing is answered; a NULL one drops it),
 * owns the handles it is given, and its arrays point into the message. */
struct crasher_ops {
    status_t (*ping)(void *ctx, uint64_t *out_started_ns);
    void (*crash)(void *ctx);
    void (*exit)(void *ctx, uint32_t code);
};

/* Answer the crasher.ping request kept in txn: idl_st and, if it is OK, the
 * results (handles are moved in every case: sent, or closed). A positive
 * status is ERR_INTERNAL, and so is OK with a handle result left
 * HANDLE_INVALID. Returns the write's status (idl_reply_write). */
static inline status_t crasher_reply_ping(struct idl_txn idl_txn, status_t idl_st, uint64_t started_ns)
{
    struct crasher_ping_rep idl_r;
    if (idl_st > 0)
        idl_st = ERR_INTERNAL;
    idl_r.status = idl_st;
    if (idl_st != OK)
        return idl_reply_write(idl_txn, &idl_r, sizeof(struct idl_rep_hdr), NULL, 0);
    idl_r.started_ns = started_ns;
    return idl_reply_write(idl_txn, &idl_r, sizeof(idl_r), NULL, 0);
}

/* Run the event (txid 0) of n bytes at m with nh handles in hs: OK, or
 * ERR_NOT_SUPPORTED (no such event, or no handler) or ERR_INVALID_ARGS
 * (it breaks the event's format), its handles closed. */
static inline status_t crasher_event_in(const struct crasher_ops *idl_tab, void *ctx,
                                        const void *idl_m, uint32_t idl_n, const handle_t *idl_hs, uint32_t idl_nh)
{
    switch (((const struct idl_req_hdr *)idl_m)->ordinal) {
    case CRASHER_CRASH: {
        const struct crasher_crash_msg *idl_e = (const struct crasher_crash_msg *)idl_m;
        uint32_t idl_o = sizeof(*idl_e);
        status_t idl_st = idl_n < sizeof(*idl_e) ? ERR_INVALID_ARGS : OK;
        if (idl_o != idl_n)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && idl_nh != 0)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && !idl_tab->crash)
            idl_st = ERR_NOT_SUPPORTED;
        if (idl_st != OK) {
            idl_close_all(idl_hs, idl_nh);
            return idl_st;
        }
        idl_tab->crash(ctx);
        return OK;
    }
    case CRASHER_EXIT: {
        const struct crasher_exit_msg *idl_e = (const struct crasher_exit_msg *)idl_m;
        uint32_t idl_o = sizeof(*idl_e);
        status_t idl_st = idl_n < sizeof(*idl_e) ? ERR_INVALID_ARGS : OK;
        if (idl_o != idl_n)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && idl_nh != 0)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && !idl_tab->exit)
            idl_st = ERR_NOT_SUPPORTED;
        if (idl_st != OK) {
            idl_close_all(idl_hs, idl_nh);
            return idl_st;
        }
        idl_tab->exit(ctx, idl_e->code);
        return OK;
    }
    }
    idl_close_all(idl_hs, idl_nh);
    return ERR_NOT_SUPPORTED;
}

/* Decode the request of n bytes at req, which came on ch, call its handler,
 * encode the reply into rep (CRASHER_REP_MAX bytes) and the handles it carries
 * into rhs (CRASHER_REP_HANDLES slots; *rhn of them). Returns the reply's
 * length: 0 means no reply (the message has no txid, a `later` handler
 * answers it itself, or it is an event: txid 0, never answered; one no
 * handler takes is dropped). No I/O; the caller sends the reply with the
 * handles, or closes them if it never sends it. */
static inline uint32_t crasher_dispatch_on(handle_t ch, const struct crasher_ops *ops, void *ctx,
                                           const void *req, uint32_t n, void *rep, handle_t *rhs,
                                           uint32_t *rhn)
{
    struct idl_rep_hdr *idl_h = (struct idl_rep_hdr *)rep;
    *rhn = 0;
    (void)rhs;
    (void)ch;
    if (n < sizeof(struct idl_req_hdr) || !((const struct idl_req_hdr *)req)->txid) {
        /* txid 0: an event (or no txid): never answered */
        if (n >= sizeof(struct idl_req_hdr))
            (void)crasher_event_in(ops, ctx, req, n, NULL, 0);
        return 0;
    }
    idl_h->txid = ((const struct idl_req_hdr *)req)->txid;
    idl_h->status = ERR_INVALID_ARGS;
    switch (((const struct idl_req_hdr *)req)->ordinal) {
    case CRASHER_CRASH:
    case CRASHER_EXIT:
        return sizeof(*idl_h);   /* an event with a txid */
    case CRASHER_PING: {
        const struct crasher_ping_req *idl_q = (const struct crasher_ping_req *)req;
        struct crasher_ping_rep *idl_r = (struct crasher_ping_rep *)rep;
        uint64_t out_started_ns = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->ping) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->ping(ctx, &out_started_ns);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->started_ns = out_started_ns;
        return sizeof(*idl_r);
    }
    }
    idl_h->status = ERR_NOT_SUPPORTED;
    return sizeof(*idl_h);
}

/* crasher_dispatch_on without the channel (the protocol has no `later` method). */
static inline uint32_t crasher_dispatch(const struct crasher_ops *ops, void *ctx, const void *req, uint32_t n,
                                        void *rep, handle_t *rhs, uint32_t *rhn)
{
    return crasher_dispatch_on(HANDLE_INVALID, ops, ctx, req, n, rep, rhs, rhn);
}

/* The unread bound (tools/genidl.py): has ch's client left CRASHER_UNREAD_MSGS
 * messages or CRASHER_UNREAD_BYTES bytes of ours unread? Then a loop of the
 * server's own reads nothing more from ch for now: it leaves ch unserved
 * and looks again later (struct idl_held). */
static inline bool crasher_unread_full(handle_t ch)
{
    return idl_unread_full(ch, CRASHER_UNREAD_MSGS, CRASHER_UNREAD_BYTES);
}

/* Take the next message on ch into slot (idl_take), a slot with room for
 * the protocol's biggest request (ERR_INVALID_ARGS if it has less). The
 * reply waiting in *rep (NULL or empty: none) goes out first in the same
 * system call (idl_take_after). It never waits: ERR_SHOULD_WAIT when
 * nothing is queued. */
static inline status_t crasher_take_slot(handle_t ch, const struct idl_slot *slot,
                                         struct idl_reply *rep)
{
    if (slot->qcap < CRASHER_REQ_MAX)
        return ERR_INVALID_ARGS;
    if (rep && rep->ch != HANDLE_INVALID)
        return idl_take_after(ch, slot, rep);
    return idl_take(ch, slot);
}

/* Run the request in slot (taken by crasher_take_slot, or found there by a
 * successor), which came on ch: as crasher_dispatch_on, its reply built
 * in slot->r and the handles that reply carries put into rhs
 * (CRASHER_REP_HANDLES slots; *rhn of them). A request that carried handles is
 * answered ERR_INVALID_ARGS without its handler seeing it. Returns the
 * reply's length: 0 means no reply (no txid, or a `later` handler
 * answers it itself). No I/O; the caller sends the reply with the handles,
 * or closes them if it never sends it. */
static inline uint32_t crasher_run_slot(handle_t ch, const struct idl_slot *slot,
                                        const struct crasher_ops *ops, void *ctx, handle_t *rhs, uint32_t *rhn)
{
    *rhn = 0;
    if (*slot->n >= sizeof(uint32_t) && *slot->nh)
        return idl_refuse(slot);
    return crasher_dispatch_on(ch, ops, ctx, slot->q, *slot->n, slot->r, rhs, rhn);
}

/* Is the method with this wire ordinal idempotent (its keyword in the
 * .idl): run again on the state its first run left, it gives the same
 * result and the same answer? A server that keeps nothing across a
 * restart may run such a request again; any other it answers with an
 * error. (No server reads it yet: it is for the drivers that outlive
 * their process, after M12.) */
static inline bool crasher_idempotent(uint32_t ordinal)
{
    (void)ordinal;
    return false;   /* no method is marked */
}

/* Take one message off ch and answer it (the unread bound is the caller's:
 * crasher_unread_full first). OK once a message was handled
 * (its reply may still have been dropped: the client is gone, or never
 * called); otherwise drv_channel_read's status: ERR_SHOULD_WAIT when
 * nothing is queued, ERR_PEER_CLOSED when the client is gone for good. */
static inline status_t crasher_serve_one(handle_t ch, const struct crasher_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[CRASHER_REQ_MAX];
    _Alignas(8) uint8_t idl_r[CRASHER_REP_MAX];
    handle_t idl_hs[IDL_READ_HANDLES];
    uint32_t idl_n = 0, idl_nh = 0;
    status_t idl_st = drv_channel_read(ch, idl_q, sizeof(idl_q), &idl_n, idl_hs, IDL_READ_HANDLES,
                                       &idl_nh);
    if (idl_st == ERR_BUFFER_TOO_SMALL)
        return idl_drain(ch, idl_n, idl_nh);
    if (idl_st != OK)
        return idl_st;
    if (idl_nh) {
        idl_close_all(idl_hs, idl_nh);
        idl_reply_status(ch, idl_q, idl_n, ERR_INVALID_ARGS);
        return OK;
    }
    handle_t idl_rhs[IDL_REP_HANDLES];
    uint32_t idl_rhn = 0;
    uint32_t idl_rn = crasher_dispatch_on(ch, ops, ctx, idl_q, idl_n, idl_r, idl_rhs, &idl_rhn);
    if (!idl_rn)
        idl_close_all(idl_rhs, idl_rhn);   /* no reply: never sent */
    else   /* the reply's handles are gone whatever the write's status */
        (void)drv_channel_write(ch, idl_r, idl_rn, idl_rhs, idl_rhn);
    return OK;
}

/* Serve ch until the client closes it (OK), or a wait or read fails
 * (that status: ERR_CANCELED when the driver is being killed). Each reply
 * goes out in the system call that takes the next request, and a client
 * with CRASHER_UNREAD_MSGS answers unread waits until it reads (idl_serve_next). */
static inline status_t crasher_serve(handle_t ch, const struct crasher_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[CRASHER_REQ_MAX];
    _Alignas(8) uint8_t idl_r[CRASHER_REP_MAX];
    handle_t idl_rhs[IDL_REP_HANDLES];
    struct idl_serve idl_s = {
        .ch = ch, .q = idl_q, .qcap = sizeof(idl_q), .r = idl_r, .rhs = idl_rhs,
        .umsgs = CRASHER_UNREAD_MSGS, .ubytes = CRASHER_UNREAD_BYTES,
    };
    for (;;) {
        status_t idl_st = idl_serve_next(&idl_s);
        if (idl_st == ERR_PEER_CLOSED)
            return OK;
        if (idl_st != OK)
            return idl_st;
        idl_s.rn = crasher_dispatch_on(ch, ops, ctx, idl_q, idl_s.n, idl_r, idl_rhs, &idl_s.rhn);
    }
}
